import React, { useState, useEffect } from 'react';
import axios from 'axios';
import PostForm from './components/PostForm';
import PostList from './components/PostList';
import './App.css';

const API_BASE_URL = '/api/posts';

function App() {
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [editingPost, setEditingPost] = useState(null);

  // Fetch all posts from the backend
  const fetchPosts = async () => {
    try {
      setLoading(true);
      const response = await axios.get(API_BASE_URL);
      setPosts(response.data);
      setError(null);
    } catch (err) {
      setError('Failed to load posts. Please check if the backend server is running.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPosts();
  }, []);

  // Create a new post
  const handleCreatePost = async (postData) => {
    try {
      const response = await axios.post(API_BASE_URL, postData);
      setPosts([response.data, ...posts]);
    } catch (err) {
      alert('Error creating post: ' + (err.response?.data?.message || err.message));
    }
  };

  // Update an existing post
  const handleUpdatePost = async (id, postData) => {
    try {
      const response = await axios.put(`${API_BASE_URL}/${id}`, postData);
      setPosts(posts.map(post => post._id === id ? response.data : post));
      setEditingPost(null);
    } catch (err) {
      alert('Error updating post: ' + (err.response?.data?.message || err.message));
    }
  };

  // Delete a post
  const handleDeletePost = async (id) => {
    if (!window.confirm('Are you sure you want to delete this post?')) return;

    try {
      await axios.delete(`${API_BASE_URL}/${id}`);
      setPosts(posts.filter(post => post._id !== id));
    } catch (err) {
      alert('Error deleting post: ' + (err.response?.data?.message || err.message));
    }
  };

  return (
    <div className="min-vh-100 pb-5">
      {/* Simple Navbar Header */}
      <nav className="navbar navbar-dark bg-primary mb-4 shadow-sm">
        <div className="container">
          <span className="navbar-brand fw-bold mb-0 h1">Blog Post Manager</span>
        </div>
      </nav>

      {/* Main Container */}
      <div className="container">
        {/* Error Alert */}
        {error && (
          <div className="alert alert-danger alert-dismissible fade show" role="alert">
            {error}
            <button type="button" className="btn-close" onClick={() => setError(null)}></button>
          </div>
        )}

        {/* Responsive Side-by-Side Grid */}
        <div className="row g-4">
          {/* Left Column: Create/Edit Post Form */}
          <div className="col-12 col-lg-5">
            <PostForm
              onSubmit={handleCreatePost}
              onUpdate={handleUpdatePost}
              editingPost={editingPost}
              onCancelEdit={() => setEditingPost(null)}
              loading={loading}
            />
          </div>

          {/* Right Column: List of Posts */}
          <div className="col-12 col-lg-7">
            <PostList
              posts={posts}
              loading={loading}
              onEdit={(post) => setEditingPost(post)}
              onDelete={handleDeletePost}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
